output_text:
[
  {
    "id": "return_taken_cart",
    "text": "A shopper who takes a cart is obliged to return or deposit that cart at the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "pushing_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "at_cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Carts may not be taken through the store exit.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "Required shelf items should only be picked up while the shopper has a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Merchandise should not be carried by hand rather than placed in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "pushing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_item_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "take_entrance_cart",
    "text": "When a shopper reaches the entrance cart station and a cart is present there, they are obliged to take the cart.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)",
        "ready_to_take_entrance_cart": {
          "and": [
            "at_entrance_cart_station",
            "cart_available_at_entrance"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "ready_to_take_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "ready_to_take_entrance_cart",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "cart_drop_only_at_return",
    "text": "A cart may only be put down at the designated return bay at (0,1), not abandoned elsewhere in the aisles.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "outside_cart_return_bay": {
          "not": "at_cart_return_bay"
        }
      },
      "events": {
        "drop_cart": {
          "pre": "LEAVE_CART",
          "post": null
        },
        "abandon_cart": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart"
    }
  },
  {
    "id": "loaded_cart_must_go_to_return",
    "text": "Once an item has been loaded into a cart, the loaded cart must eventually be taken to the return bay and left there.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "load_item_into_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "pushing_cart"
            ]
          },
          "post": "pushing_cart"
        },
        "return_loaded_cart": {
          "pre": {
            "and": [
              "at_cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "load_item_into_cart",
      "discharge": "return_loaded_cart"
    }
  },
  {
    "id": "no_carts_in_exit_side_zone",
    "text": "Carts are forbidden in the exit-side zone of the supermarket, so shoppers must leave the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "exit_side_zone": {
          "ge": [
            "x",
            7
          ]
        },
        "cart_in_exit_side_zone": {
          "and": [
            "pushing_cart",
            "exit_side_zone"
          ]
        }
      },
      "events": {
        "enter_exit_side_with_cart": {
          "pre": "cart_in_exit_side_zone",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_exit_side_zone"
    }
  }
]
